from html.parser import HTMLParser
import sys
class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_algo=False; self.in_h2=False; self.in_a=False; self.in_p=False; self.url=''; self.buf=[]; self.items=[]; self.depth=0
    def handle_starttag(self,t,a):
        d=dict(a)
        if t=='li' and 'b_algo' in d.get('class','').split(): self.in_algo=True; self.item={'url':None,'title':'','text':''}
        elif self.in_algo and t=='h2': self.in_h2=True
        elif self.in_algo and t=='a' and self.in_h2: self.in_a=True; self.item['url']=d.get('href')
        elif self.in_algo and t in ('p','div'): self.in_p=True
    def handle_endtag(self,t):
        if t=='a' and self.in_a: self.in_a=False
        elif t=='h2': self.in_h2=False
        elif t=='li' and self.in_algo:
            self.items.append(self.item); self.in_algo=False
        elif t in ('p','div'): self.in_p=False
    def handle_data(self,d):
        if self.in_algo:
            s=' '.join(d.split())
            if s:
                if self.in_h2: self.item['title'] += (' ' if self.item['title'] else '')+s
                self.item['text'] += (' ' if self.item['text'] else '')+s
p=P(); p.feed(open(sys.argv[1], errors='ignore').read())
for x in p.items[:10]: print(x)
